VALUES (8839, 'tt0112642', NULL, 'Casper', 'Casper', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/2ah8fNJFZVU3vcXhU5xfAYi2eym.jpg', 'https://image.tmdb.org/t/p/original/sQPckU0TfSeYIlUneHfIXwzQC2f.jpg', 'Casper is a kind young ghost who peacefully haunts a mansion in Maine. When specialist James Harvey arrives to communicate with Casper and his fellow spirits, he brings along his teenage daughter, Kat. Casper quickly falls in love with Kat, but their budding relationship is complicated not only by his transparent state, but also by his troublemaking apparition uncles and their mischievous antics.', NULL, NULL, 9.9417, 6.353, 0, 23.3665, '2026-07-15 12:01:52', '2026-11-08 06:20:12')
