VALUES (32489, 'tt0062362', NULL, 'Thoroughly Modern Millie', 'Thoroughly Modern Millie', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/ce8rBGFR0naGsp6mKy9CNKn9iSa.jpg', 'https://image.tmdb.org/t/p/original/ufekY2p0zR41eAeKDrqpmylDa6K.jpg', 'Millie Dillmount, a fearless young lady fresh from Salina, Kansas, determined to experience Life, sets out to see the world in the rip-roaring Twenties. With high spirits and wearing one of those new high hemlines, she arrives in New York to test the "modern" ideas she had been reading about back in Kansas: "I''ve taken the girl out of Kansas. Now I have to take Kansas out of the girl!"', NULL, NULL, 1.3756, 6.864, 0, 8.70333333333333314e+00, '2026-08-06 03:21:20', '2026-11-08 06:20:12')
