VALUES (17281, 'tt0051658', NULL, 'Gigi', 'Gigi', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/3GSuecnDr4N5ZaqTrwElSzt6eC2.jpg', 'https://image.tmdb.org/t/p/original/6aIpiwQB2qvVHSlhsXYZD3lmmSV.jpg', 'A home, a motorcar, servants, the latest fashions: the most eligible and most finicky bachelor in Paris offers them all to Gigi. But she, who''s gone from girlish gawkishness to cultured glamour before our eyes, yearns for that wonderful something money can''t buy.', NULL, NULL, 3.1361, 6.233, 0, 10.275, '2026-08-26 01:43:46', '2026-11-08 06:20:12')
