VALUES (1742441, 'tt43739386', NULL, 'V/H/S/MIXTAPE', 'V/H/S/MIXTAPE', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/uS8yoiA6NfsuYeOTbVfpem8Ib9.jpg', 'https://image.tmdb.org/t/p/original/yIDZiYea2Bah1yLYz14jlC89WJ5.jpg', 'V/H/S/MIXTAPE cranks the volume on horror with a blood-soaked collection of cursed music videos, terrifying performances, and found footage. Press play. Pray it stops.', NULL, NULL, 27.3386, 4.583, 0, 6.325, '2026-10-30 06:04:41', '2026-11-08 06:20:12')
